# -*- coding: utf-8 -*-
import os

from taf.playwright.core.artifacts import ArtifactManager
from taf.playwright.core.session import SessionStore
from taf.playwright.sbts.provider import Provider


class CloseableSession(object):
    def __init__(self):
        self.closed = False

    def close(self):
        self.closed = True


def test_artifact_manager_uses_explicit_directories(tmp_path):
    manager = ArtifactManager("download_suffix", "screenshot_suffix")
    download_dir = manager.download_dir(str(tmp_path / "downloads"))
    screenshot_dir = manager.screenshot_dir(download_dir, str(tmp_path / "screenshots"))

    assert os.path.isdir(download_dir)
    assert os.path.isdir(screenshot_dir)


def test_session_store_add_get_remove_close():
    store = SessionStore()
    default_session = CloseableSession()
    named_session = CloseableSession()

    store.add(default_session)
    store.add(named_session, "sbts1")

    assert store.get() is default_session
    assert store.get("sbts1") is named_session
    assert store.remove("sbts1") is named_session

    store.close_all()
    assert default_session.closed


def test_sbts_provider_supports_legacy_release_names():
    assert Provider.provide("SBTS20B").__name__ == "Sbts20B"
    assert Provider.provide("SBTS26R3").__name__ == "Sbts26R3"
    assert Provider.provide("").__name__ == "Sbts26R3"
